architecture.h4_f:
msg = CBOR{v:1, teksto, respondi_al, sendita_je}
ct = AES-GCM-256-Ĉifri (k, nonce, msg, aad=ĉambro_id)
POST /api/rooms/{id}/messages {ĉifrteksto: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, teksto, respond_al?, thread_id?, mencioj?, sent_at}
ct = AES-GCM-256-Ĉifri (ĉambro_ŝlosilo, nonce, pt, aad=hex (ĉambro_id))
drato = CBOR{
  v: 1,
  ĉifroteksto: hex(ct), // varia longeco
  nefoje: hex(12 B),
  sendanto_pseŭdo: hex(16 B),
  sendita_ĉe: unix_ms
}

cryptoWire.h5_f:
ekstera = CBOR{
  fonto_nodo: hex32,
  cel_uzanto: int64,
  interna_ĉifrteksto: bajtoj,
  inner_nonce: bajtoj,
  sendita_ĉe: unix_ms
}
sig = Ed25519-Sign (fonto_priv, ekstera)
POST /federacio/liver { koverto: ekstera, sig: hex64 }

auth.h1_f:
POST /api/authentication/register
  { uzantnomo, pasvorto, x25519_public_key, display_name, telefono?, retpoŝto?, avatar_emoji }

Respondo 201 Kreita:
  { access_token, refresh_token, user_id, uzantnomo, ... }

auth.h3_f:
access_token utila ŝarĝo:
  { sub: user_id, jti: device_id, tajpu: "aliro", eksp: nun + 15min }
refresh_token utila ŝarĝo:
  { sub: user_id, jti: device_id, tajpu: "refreŝigi", eksp: nun + 30d }

HS256-subskribita kun la 64-bajta sekreto de nodo de .env

auth.h4_f:
register_begin(): defio = rand(32)
                    opcioj = { rp.id, user.id, pubKeyCredParams, defio }
                    revenopcioj

registri_fino(atesto):
  kontroli ateston kontraŭ TPM/Secure Enclave radiko CA
  stoku { credential_id, publika_ŝlosilo, nombrilo: 0}

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bita dekseso, ttl: 60 }
QR utila ŝarĝo = { nonce, user_id, servilo: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → nova aparato registrita; JWToj revenis.

rooms.h6_f:
sendanto_pseŭdo = HMAC-SHA256(ĉambro_pseŭdo_salo, sendinto_id)[:16] // 32 hex
ĉifroteksto = AES-GCM-Ĉifri (ĉambro_ŝlosilo, nonce, CBOR_utila ŝarĝo, aad=ĉambro_id)

Ventila kadro: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {dosiernomo, grandeco, chunk_size_hint}
            ← {alŝuto_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bajtoj>
            ← 204
fini POST /api/files/resumable/{upload_id}/finalize {plain_blake3}
            ← 201 {file_id, url}
TTL je nefinita: 24 h

files.h4_f:
deny_list = {
  "aplikaĵo/x-dosexec",
  "aplikaĵo/x-sharedlib",
  "aplikaĵo/x-mach-binara",
}
if magic.from_buffer(buf[:1024]) en deny_list: redonu 415

presence.h1_f:
kliento: ĉe la unua klavopremo → sendu {tipo:"t", stato:"komenco"}
         ne plu sendas dum 3 s krom se stato ŝanĝiĝas
         10 s post lasta klavopremo → sendu {tipo:"t", stato:"halti"}
ricevilo: aŭtomata halto 10 s post lasta "komenco" se neniu "halto" alvenis

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS elsendo {tipo:"c", speco:"inviti", call_id}
WS elsendo {tipo:"c", speco:"oferto", sdp}
WS elsendo {tipo:"c", speco:"respondo", sdp}
WS elsendo {tipo:"c", speco:"kandidato", glacio} × N
POST /api/calls/{call_id}/end

federation.h2_f:
koverto = {
  fonto_nodo : hex32,
  celo_uzanto : int64,
  interna_ĉifrteksto: bajtoj,
  inner_nonce : bajtoj,
  sent_at : unix_ms,
}
sig = Ed25519Sign(fonto_priv, CBOR(koverto))
POST /federacio/liver { koverto, sig }

gossip.h3_f:
reklamo = {pubkey, finpunkto, reklamita_ĉe}
sig = Ed25519-Sign(pubkey_priv, CBOR(reklamo))
klaĉa utila ŝarĝo: [..., {ad, sig}, ...]

ricevilo: kontroli sig kontraŭ ad.pubkey → stoki se bone
kroma: PoW de 2^18 antaŭaj nuloj sur {pubkey, endpoint}

stealth.h2_f:
ClientHello bajtoj = chrome_120_template kun {
  hazarda = nia hazarda,
  server_name = nia gastiga nomo (aŭ ECH-envolvita),
  session_id = nia sesioid,
}
JA4 = t13d_xxxx_xxxx_xxxx (kongruas kun nuna Chrome stabila)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {nomo: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: domajno(t) = bazo32( SHA256(semo ∥ YYYY-MM-DD) )[:16] + ".ekzemplo"

push.h4_f:
iOS NSE: didReceive (peto) { malĉifri (request.content.userInfo) }
Android FCM: onMessageReceived (remoteMessage) { malĉifri (remoteMessage.data) }
Retejo SW: self.addEventListener('push', e => deĉifri(e.datenoj))

controller.h2_f:
ilo = sign_tool
enigo = fonta arbo, keys/release.key
manifesto = {
  versio: "0.1.0",
  konstruita_ĉe: unix_ms,
  dosieroj: [[pado, sha256, grandeco}, ...]
}
sig = Ed25519-Sign(liberigo_priv, CBOR(manifesto))
eligo = INTEGRITY.sig.json = {manifesto, subskribita_de: pub_hex, sig: sig_hex}

bots.h1_f:
kreu: POST /api/bots {uzantnomo, montra_nomo, kodo}
          → {bot_id, ĵetono, pubkey}
kuri: enproceza (korutino ene de nodo)
      OR ekstera (long-enketo /api/bots/{id}/ĝisdatigoj, token-aŭth'd)
mesaĝo: {teksto, subskribo: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
sur /komenco {
  elsendi "Bonvenon, {ctx.first_name}"
}
sur /aldonu <ero> {
  stato.listo = (ŝtato.listo aŭ []) + [ctx.args.item]
  elsendi "Aldonita: {ctx.args.item}"
}

security.h4_f:
canary.txt (ĉiutage):
  {dato, sig: Ed25519-Sign(liberigo_priv, dato)}
kliento kontrolas → forestanta aŭ nevalida ⇒ kompromiso suspektita

krizo:
  administranto POST /api/admin/revoke-all {kialo}
  nodo elsendas {tipo:"n", evento:"kompromiso", kialo}
  klientoj viŝi ŝlosilojn, devigi re-bootstrap

debugging.h2_f:
taksi histogramojn (po itinero + metodo):
  vortex_http_requests_total{itinero, metodo, stato}
  vortex_http_request_duration_seconds_bucket{itinero,metodo,le}

Websocket mezuriloj:
  vortex_ws_connections{nodo}
  vortex_ws_fanout_queue_depth{ĉambro,uzanto}

Propraj nombriloj:
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{kind}

